INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Müssen Mitarbeiterdaten immer physisch gespeichert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Digitale Speicherung ist möglich"}, {"text": "Ja", "correct": false, "because": "Digitale Systeme üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel bei der Verwaltung von Mitarbeiterdaten?', 3, '[{"text": "Datenschutz", "correct": true, "because": "Schützt sensible Informationen"}, {"text": "Öffentliche Freigabe", "correct": false, "because": "Verletzt Datenschutz"}, {"text": "Manuelle Archivierung", "correct": false, "because": "Ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten gehören typischerweise in eine solche Akte?', 5, '[{"text": "Gehaltsabrechnungen", "correct": true, "because": "Dokumentieren Vergütung"}, {"text": "Verträge", "correct": true, "because": "Regeln Arbeitsverhältnis"}, {"text": "Fotosammlung", "correct": false, "because": "Nicht arbeitsrelevant"}, {"text": "Social-Media-Profile", "correct": false, "because": "Privatsphäre geschützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Personalakten unterliegen der DSGVO. b) Sie dürfen öffentlich eingesehen werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) verletzt Datenschutz"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Verwaltung von Mitarbeiterdaten?', 4, '[{"text": "Zugriffsbeschränkungen", "correct": false, "because": "Schützen Vertraulichkeit"}, {"text": "Speicherfristen", "correct": false, "because": "Gesetzlich vorgeschrieben"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant für Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Personalakten immer digital sein müssen?', 2, '[{"text": "Nein", "correct": true, "because": "Papierakten noch erlaubt"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend digital"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium ist für die Datenspeicherung entscheidend?', 3, '[{"text": "Sicherheitsmaßnahmen", "correct": true, "because": "Schützen sensible Daten"}, {"text": "Öffentliche Zugänglichkeit", "correct": false, "because": "Verletzt DSGVO"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen sichern die Verwaltung von Mitarbeiterdaten?', 5, '[{"text": "Verschlüsselung", "correct": true, "because": "Schützt Datenintegrität"}, {"text": "Zugriffskontrollen", "correct": true, "because": "Begrenzen unbefugten Zugriff"}, {"text": "Öffentliche Freigabe", "correct": false, "because": "Verletzt Datenschutz"}, {"text": "Manuelle Backups", "correct": false, "because": "Automatisierung sicherer"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Personalakten müssen gesetzeskonform sein. b) Sie dürfen an Dritte verkauft werden. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) verletzt Datenschutz"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Verwaltung von Mitarbeiterdaten?', 4, '[{"text": "Datenschutzrichtlinien", "correct": false, "because": "Gesetzlich vorgeschrieben"}, {"text": "Sichere Speicherung", "correct": false, "because": "Schützt Daten"}, {"text": "Öffentliche Datenbanken", "correct": true, "because": "Verletzt Vertraulichkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Dürfen Personalakten unbegrenzt gespeichert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Löschfristen gelten"}, {"text": "Ja", "correct": false, "because": "DSGVO setzt Grenzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Systeme unterstützen die Verwaltung von Mitarbeiterdaten?', 4, '[{"text": "HR-Software", "correct": true, "because": "Automatisiert Prozesse"}, {"text": "DMS", "correct": true, "because": "Sichert Dokumente"}, {"text": "Spieleplattformen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Personalakten immer öffentlich einsehbar sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Datenschutz verbietet das"}, {"text": "Ja", "correct": false, "because": "Vertraulichkeit vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Speicherung von Mitarbeiterdaten?', 3, '[{"text": "Zugriffssicherheit", "correct": true, "because": "Schützt vor Missbrauch"}, {"text": "Maximale Freigabe", "correct": false, "because": "Verletzt DSGVO"}, {"text": "Manuelle Verwaltung", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Personalakten müssen verschlüsselt sein. b) Sie dürfen an alle Mitarbeiter verteilt werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) verletzt Datenschutz"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine digitale Verwaltung von Mitarbeiterdaten?', 5, '[{"text": "Schneller Zugriff", "correct": true, "because": "Vereinfacht Verwaltung"}, {"text": "Höhere Sicherheit", "correct": true, "because": "Durch Verschlüsselung"}, {"text": "Öffentliche Freigabe", "correct": false, "because": "Verletzt Datenschutz"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Verwaltung von Mitarbeiterdaten unwichtig?', 3, '[{"text": "Löschfristen", "correct": false, "because": "Gesetzlich vorgeschrieben"}, {"text": "Zugriffskontrollen", "correct": false, "because": "Schützen Daten"}, {"text": "Musikwiedergabe", "correct": true, "because": "Kein Datenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Müssen Personalakten immer verschlüsselt sein?', 3, '[{"text": "Ja", "correct": true, "because": "Schützt sensible Daten"}, {"text": "Nein", "correct": false, "because": "Verschlüsselung empfohlen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Personalakten für alle Mitarbeiter einsehbar sind?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Berechtigte haben Zugriff"}, {"text": "Ja", "correct": false, "because": "Datenschutz schränkt ein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zur Verwaltung von Mitarbeiterdaten?', 4, '[{"text": "Speicherung von Arbeitsverträgen", "correct": true, "because": "Teil der Personalakte"}, {"text": "Erstellung eines Logos", "correct": false, "because": "Gestalterische Aufgabe"}, {"text": "Netzwerkkonfiguration", "correct": false, "because": "Technische Aufgabe"}]');
